-- Initial persistent backend schema for Kikoba
CREATE TYPE "GoalStatus" AS ENUM ('DRAFT','ACTIVE','PAUSED','COMPLETED','CANCELLED','EXPIRED');
CREATE TYPE "ContributionStatus" AS ENUM ('PENDING','PARTIAL','ON_TIME','GRACE','LATE','MISSED','RECOVERED');
CREATE TYPE "DepositStatus" AS ENUM ('PENDING','SUCCESSFUL','FAILED','REVERSED');
CREATE TYPE "AllocationMode" AS ENUM ('EXPLICIT','AUTO_ALLOCATE');
CREATE TYPE "Priority" AS ENUM ('HIGH','NORMAL','LOW');
CREATE TYPE "EventType" AS ENUM ('DEPOSIT_SUCCESS','DEPOSIT_REVERSED','CONTRIBUTION_COMPLETED','CONTRIBUTION_PARTIAL','CONTRIBUTION_LATE','CONTRIBUTION_MISSED','CONTRIBUTION_RECOVERED','GOAL_COMPLETED','GOAL_CANCELLED','GOAL_EXPIRED','CHAMA_JOINED','CHAMA_LEFT','WITHDRAWAL_COMPLETED');
CREATE TYPE "ChamaType" AS ENUM ('LONG_TERM','SHORT_TERM'); CREATE TYPE "ChamaFrequency" AS ENUM ('WEEKLY','MONTHLY'); CREATE TYPE "MembershipRole" AS ENUM ('CREATOR','ADMIN','MEMBER'); CREATE TYPE "MembershipStatus" AS ENUM ('ACTIVE','LEFT','REMOVED','PENDING'); CREATE TYPE "FriendRequestStatus" AS ENUM ('PENDING','ACCEPTED','DECLINED','BLOCKED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"username" TEXT NOT NULL UNIQUE,"profilePhotoUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Chama" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT,"type" "ChamaType" NOT NULL,"contribution" DECIMAL(18,2) NOT NULL,"frequency" "ChamaFrequency" NOT NULL,"maxMembers" INTEGER NOT NULL,"minTier" TEXT NOT NULL,"goal" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"ownerId" TEXT NOT NULL REFERENCES "User"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ChamaMember" ("id" TEXT PRIMARY KEY,"chamaId" TEXT NOT NULL REFERENCES "Chama"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "MembershipRole" NOT NULL DEFAULT 'MEMBER',"status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leftAt" TIMESTAMP(3),UNIQUE("chamaId","userId"));
CREATE TABLE "FriendRequest" ("id" TEXT PRIMARY KEY,"fromId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"toId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"status" "FriendRequestStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Friendship" ("id" TEXT PRIMARY KEY,"userAId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"userBId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userAId","userBId"));
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY,"chamaId" TEXT UNIQUE REFERENCES "Chama"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ConversationMember" ("id" TEXT PRIMARY KEY,"conversationId" TEXT NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("conversationId","userId"));
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY,"conversationId" TEXT NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE,"senderId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"editedAt" TIMESTAMP(3));
CREATE TABLE "SavingsGoal" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"targetAmount" DECIMAL(18,2) NOT NULL,"targetDate" TIMESTAMP(3),"expectedAmount" DECIMAL(18,2) NOT NULL,"frequency" TEXT NOT NULL,"priority" "Priority" NOT NULL DEFAULT 'NORMAL',"status" "GoalStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ExpectedContribution" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"goalId" TEXT REFERENCES "SavingsGoal"("id") ON DELETE SET NULL,"expectedAmount" DECIMAL(18,2) NOT NULL,"amountPaid" DECIMAL(18,2) NOT NULL DEFAULT 0,"dueDate" TIMESTAMP(3) NOT NULL,"gracePeriodEnd" TIMESTAMP(3) NOT NULL,"status" "ContributionStatus" NOT NULL DEFAULT 'PENDING',"completedAt" TIMESTAMP(3),"recoveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Deposit" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"amount" DECIMAL(18,2) NOT NULL,"destinationGoalId" TEXT,"allocationMode" "AllocationMode" NOT NULL DEFAULT 'EXPLICIT',"status" "DepositStatus" NOT NULL DEFAULT 'PENDING',"source" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reversedAt" TIMESTAMP(3));
CREATE TABLE "DepositAllocation" ("id" TEXT PRIMARY KEY,"depositId" TEXT NOT NULL REFERENCES "Deposit"("id") ON DELETE CASCADE,"contributionId" TEXT NOT NULL REFERENCES "ExpectedContribution"("id") ON DELETE CASCADE,"amount" DECIMAL(18,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reversedAt" TIMESTAMP(3));
CREATE TABLE "FinancialEvent" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"type" "EventType" NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ScoreFeature" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"consistency" DOUBLE PRECISION NOT NULL,"goalCompletion" DOUBLE PRECISION NOT NULL,"streak" DOUBLE PRECISION NOT NULL,"amountReliability" DOUBLE PRECISION NOT NULL,"timing" DOUBLE PRECISION NOT NULL,"recovery" DOUBLE PRECISION NOT NULL,"momentum" DOUBLE PRECISION NOT NULL,"commitmentLoad" DOUBLE PRECISION NOT NULL,"participationReliability" DOUBLE PRECISION NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"eventCount" INTEGER NOT NULL,"calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UserScore" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"score" INTEGER NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"profile" TEXT NOT NULL,"reason" TEXT,"featureSnapshot" JSONB NOT NULL,"calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Chama_status_type_frequency_idx" ON "Chama"("status","type","frequency"); CREATE INDEX "Chama_ownerId_idx" ON "Chama"("ownerId"); CREATE INDEX "ChamaMember_userId_status_idx" ON "ChamaMember"("userId","status"); CREATE INDEX "ChamaMember_chamaId_status_idx" ON "ChamaMember"("chamaId","status"); CREATE INDEX "FriendRequest_toId_status_idx" ON "FriendRequest"("toId","status"); CREATE INDEX "FriendRequest_fromId_status_idx" ON "FriendRequest"("fromId","status"); CREATE INDEX "Friendship_userAId_idx" ON "Friendship"("userAId"); CREATE INDEX "Friendship_userBId_idx" ON "Friendship"("userBId"); CREATE INDEX "ConversationMember_userId_idx" ON "ConversationMember"("userId"); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt"); CREATE INDEX "ExpectedContribution_userId_dueDate_status_idx" ON "ExpectedContribution"("userId","dueDate","status"); CREATE INDEX "DepositAllocation_depositId_idx" ON "DepositAllocation"("depositId"); CREATE INDEX "DepositAllocation_contributionId_idx" ON "DepositAllocation"("contributionId"); CREATE INDEX "FinancialEvent_userId_createdAt_idx" ON "FinancialEvent"("userId","createdAt"); CREATE INDEX "UserScore_userId_calculatedAt_idx" ON "UserScore"("userId","calculatedAt");
